export async function createScene(engine, canvas, BABYLON) {
  var scene = new BABYLON.Scene(engine);
  scene.clearColor = BABYLON.Color4.FromHexString("#D74502FF");

  const LEFT_MASK = 0x10;
  const RIGHT_MASK = 0x20;
  const UI_MASK = 0x40;
  const BOTH_MASK = LEFT_MASK | RIGHT_MASK;

  var cameraLeft = new BABYLON.ArcRotateCamera("cameraLeft", 2.347, 1.05, 46.99, new BABYLON.Vector3(0, 1.5, 0), scene);
  cameraLeft.viewport = new BABYLON.Viewport(0, 0, 0.5, 1);
  cameraLeft.layerMask = LEFT_MASK; // 왼쪽 마스크만 렌더링
  cameraLeft.attachControl(canvas, true);

  var cameraRight = new BABYLON.ArcRotateCamera("cameraRight", 2.347, 1.05, 46.99, new BABYLON.Vector3(0, 1.5, 0), scene);
  cameraRight.viewport = new BABYLON.Viewport(0.5, 0, 0.5, 1);
  cameraRight.layerMask = RIGHT_MASK; // 오른쪽 마스크만 렌더링

  var uiCamera = new BABYLON.FreeCamera("uiCamera", BABYLON.Vector3.Zero(), scene);
  uiCamera.layerMask = UI_MASK;
  uiCamera.viewport = new BABYLON.Viewport(0.5, 0, 0.5, 1);
  uiCamera.clearFlags = BABYLON.Camera.NONE;

  scene.activeCameras = [cameraLeft, cameraRight, uiCamera];

  scene.onBeforeRenderObservable.add(() => {
    cameraRight.alpha = cameraLeft.alpha;
    cameraRight.beta = cameraLeft.beta;
    cameraRight.radius = cameraLeft.radius;
    cameraRight.target.copyFrom(cameraLeft.target);
  });

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.3;
  light.includeOnlyWithLayerMask = BOTH_MASK;

  var spotLight = new BABYLON.SpotLight(
    "spotLight",
    new BABYLON.Vector3(8.54, 6.17, -2.26),
    new BABYLON.Vector3(-0.89, -0.26, 0.37),
    BABYLON.Tools.ToRadians(145.8),
    2,
    scene,
  );
  spotLight.intensity = 150;
  spotLight.includeOnlyWithLayerMask = RIGHT_MASK; // 오른쪽에서만 작동

  var spotLight2 = new BABYLON.SpotLight(
    "spotLight2",
    new BABYLON.Vector3(-7.63, 10.97, -17.53),
    new BABYLON.Vector3(0.14, -0.45, 0.88),
    Math.PI / 3,
    2,
    scene,
  );
  spotLight2.intensity = 8000;
  spotLight2.diffuse = BABYLON.Color3.FromHexString("#FF6F07");
  spotLight2.includeOnlyWithLayerMask = RIGHT_MASK;

  var pointLight = new BABYLON.PointLight("pointLight", new BABYLON.Vector3(-2.22, 16.91, -2.16), scene);
  pointLight.intensity = 200;
  pointLight.diffuse = BABYLON.Color3.FromHexString("#EE0000");
  pointLight.includeOnlyWithLayerMask = RIGHT_MASK;

  var shadowGenerator = new BABYLON.ShadowGenerator(1024, spotLight);
  shadowGenerator.useExponentialShadowMap = true;
  var shadowGenerator2 = new BABYLON.ShadowGenerator(1024, spotLight2);
  shadowGenerator2.useContactHardeningShadow = true;
  var shadowGenerator3 = new BABYLON.ShadowGenerator(1024, pointLight);

  var defaultPipeline = new BABYLON.DefaultRenderingPipeline("default", true, scene, [cameraRight]);
  defaultPipeline.glowLayerEnabled = true;
  defaultPipeline.glowLayer.intensity = 0.3;
  defaultPipeline.fxaaEnabled = true;
  defaultPipeline.grainEnabled = true;
  defaultPipeline.grain.intensity = 11;
  defaultPipeline.imageProcessingEnabled = true;
  defaultPipeline.imageProcessing.vignetteEnabled = true;
  defaultPipeline.imageProcessing.vignetteWeight = 4;
  defaultPipeline.imageProcessing.vignetteCameraFov = 0.8;

  let shadowToggle = true;
  let postToggle = true;
  let lightToggle = true;

  // 조명 원본 강도 저장
  const ORIGIN_INTENSITY = {
    spot: 100,
    spot2: 5000,
    point: 110,
  };

  let targetShadowDarkness = 0;
  let targetGlow = 0.3;
  let targetGrain = 11;
  let targetVignette = 4;

  // 조명 목표 강도
  let targetSpotIntensity = ORIGIN_INTENSITY.spot;
  let targetSpot2Intensity = ORIGIN_INTENSITY.spot2;
  let targetPointIntensity = ORIGIN_INTENSITY.point;

  // 매 프레임 부드럽게 보간 (Lerp)
  scene.onBeforeRenderObservable.add(() => {
    const lerpSpeed = 0.1;

    // 1. 그림자 업데이트
    [shadowGenerator, shadowGenerator2, shadowGenerator3].forEach((sg) => {
      sg.darkness = BABYLON.Scalar.Lerp(sg.darkness, targetShadowDarkness, lerpSpeed);
    });

    // 2. 포스트 프로세스 업데이트
    if (defaultPipeline.glowLayer) {
      defaultPipeline.glowLayer.intensity = BABYLON.Scalar.Lerp(defaultPipeline.glowLayer.intensity, targetGlow, lerpSpeed);
    }
    defaultPipeline.grain.intensity = BABYLON.Scalar.Lerp(defaultPipeline.grain.intensity, targetGrain, lerpSpeed);

    if (defaultPipeline.imageProcessingEnabled)
      defaultPipeline.imageProcessing.vignetteWeight = BABYLON.Scalar.Lerp(defaultPipeline.imageProcessing.vignetteWeight, targetVignette, lerpSpeed);

    // 3. 조명 강도 업데이트 (부드러운 On/Off)
    spotLight.intensity = BABYLON.Scalar.Lerp(spotLight.intensity, targetSpotIntensity, lerpSpeed);
    spotLight2.intensity = BABYLON.Scalar.Lerp(spotLight2.intensity, targetSpot2Intensity, lerpSpeed);
    pointLight.intensity = BABYLON.Scalar.Lerp(pointLight.intensity, targetPointIntensity, lerpSpeed);
  });

  var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");
  advancedTexture.layer.layerMask = UI_MASK;

  var panel = new BABYLON.GUI.StackPanel();
  panel.width = "200px";
  panel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_RIGHT;
  panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_BOTTOM;
  panel.paddingBottom = "20px";
  advancedTexture.addControl(panel);

  const createBtn = (text, bgColor, action) => {
    var btn = BABYLON.GUI.Button.CreateSimpleButton(text, text);
    btn.width = "160px";
    btn.height = "40px";
    btn.color = "white";
    btn.background = bgColor;
    btn.marginBottom = "8px";
    btn.onPointerClickObservable.add(action);
    panel.addControl(btn);
    return btn;
  };

  createBtn("Lights On/Off", "#D4AF37", () => {
    lightToggle = !lightToggle;
    targetSpotIntensity = lightToggle ? ORIGIN_INTENSITY.spot : 0;
    targetSpot2Intensity = lightToggle ? ORIGIN_INTENSITY.spot2 : 0;
    targetPointIntensity = lightToggle ? ORIGIN_INTENSITY.point : 0;
  });

  createBtn("Shadow On/Off", "#333", () => {
    shadowToggle = !shadowToggle;
    targetShadowDarkness = shadowToggle ? 0 : 1;
  });

  createBtn("Post Process On/Off", "#555", () => {
    postToggle = !postToggle;
    targetGlow = postToggle ? 0.3 : 0;
    targetGrain = postToggle ? 11 : 0;
    targetVignette = postToggle ? 4 : 0;

    defaultPipeline.imageProcessingEnabled = postToggle ? true : false;
  });

  BABYLON.SceneLoader.Append("https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "isometric_bedroom.glb", scene, function (newMeshes) {
    const rootMesh = newMeshes.meshes[0];
    rootMesh.scaling.scaleInPlace(0.1);

    const myClonedModel = deepCloneHierarchy(rootMesh, null);
    myClonedModel.getChildMeshes().forEach((m) => {
      m.layerMask = LEFT_MASK;

      // if (m.name.includes("Cube.023_Material.008_0")) {
      //     m.material.emissiveColor = BABYLON.Color3.Black();
      // }
    });

    rootMesh.getChildMeshes().forEach((m) => {
      m.layerMask = RIGHT_MASK;

      if (m.name !== "Cube.002_Material_0") {
        m.receiveShadows = true;
      }
      if (m.name !== "Cube.024_Material_0" && m.name !== "Cube.052_Material.021_0") {
        shadowGenerator.addShadowCaster(m);
        shadowGenerator2.addShadowCaster(m);
      }
      shadowGenerator3.addShadowCaster(m);
    });
  });

  function deepCloneHierarchy(node, newParent = null) {
    const clonedNode = node.clone(node.name + "_clone", newParent, true);

    if (clonedNode.material) {
      clonedNode.material = clonedNode.material.clone(clonedNode.name + "_mat");
    }

    const children = node.getChildren();
    for (const child of children) {
      deepCloneHierarchy(child, clonedNode);
    }

    return clonedNode;
  }

  return scene;
}
